import type { Meta, StoryObj } from '@storybook/html-vite';
import { expect } from 'storybook/test';

import { mountHudStage } from '../../.storybook/hud-stage';
import recorded from '../../test/fixtures/youtube-timedtext-broadcast-captions.json';
import { queryPlayerUi } from '../ui/root';

import { CaptionRenderer } from './caption-renderer';
import { parseCaptionPayload } from './parsers/captions';

interface Args { track: 'asr' | 'cc1'; time: number }

/**
 * Two recorded tracks of one YouTube video (sanitized json3), shown at the moment of a bug report: the
 * auto-generated track and the broadcast's CC1, which arrives two characters at a time and in upper case. The
 * parser, renderer, stylesheet and shadow root are production code.
 */
function render({ track, time }: Args): HTMLElement {
  const stage = mountHudStage({ progress: 1 });
  const renderer = new CaptionRenderer();
  renderer.setCues(parseCaptionPayload(JSON.stringify(recorded.tracks[track].body)));
  renderer.update(time);
  stage.onDispose(() => renderer.dispose());
  stage.settle();
  return stage.view;
}

const meta: Meta<Args> = {
  title: 'Components/Caption overlay',
  args: { track: 'cc1', time: 88 },
  argTypes: { track: { control: 'select', options: ['asr', 'cc1'] }, time: { control: { type: 'range', min: 84, max: 90, step: 0.05 } } },
  render
};
export default meta;

export const BroadcastCaptions: StoryObj<Args> = { play: async () => {
  await expect(queryPlayerUi<HTMLElement>('.theater-caption-overlay-text')?.innerText).toBe("CERTAINLY HERE. BUT IT WASN'T\nJUST HERE IN THE FIRST DISTRICT");
} };

export const AutoGenerated: StoryObj<Args> = { args: { track: 'asr' }, play: async () => {
  await expect(queryPlayerUi<HTMLElement>('.theater-caption-overlay-text')?.innerText).toBe("North Carolina screen because I think\nthere's a much bigger story in North");
} };
